import random
import itertools

def check_condition(n, max_coeff=10, max_a=20):
    # For each d from 1 to n
    for d in range(1, n + 1):
        # Test several random polynomials Q(x) of degree < d
        for _ in range(10):
            coeffs = [random.randint(-max_coeff, max_coeff) for _ in range(d)]
            # Q(x) = sum(coeffs[i] * x^i)
            def Q(x):
                res = 0
                for i in range(d):
                    res += coeffs[i] * (x**i)
                return res

            def f(x):
                return x**d - Q(x)

            # Check if there exists k in {1, ..., n} and distinct a_1, ..., a_{k+1}
            found = False
            # To make the search feasible, we limit the range of a_i
            # We search for a_i in [-max_a, max_a]
            # This is a very limited search.

            # Try k from 1 to n
            for k in range(1, n + 1):
                # We need k+1 distinct integers a_1, ..., a_{k+1}
                # Search for them. This is the hard part.
                # Let's try a random search or a small brute force.
                # Brute force for small n, k, max_a
                for a_vals in itertools.combinations(range(-max_a, max_a + 1), k + 1):
                    # a_vals is a tuple of k+1 distinct integers.
                    # Any one of them could be a_{k+1}.
                    for idx in range(k + 1):
                        ak_plus_1 = a_vals[idx]
                        others = [a_vals[j] for j in range(k + 1) if j != idx]
                        if f(ak_plus_1) == sum(f(a) for a in others):
                            found = True
                            break
                    if found: break
                if found: break

            if not found:
                return False, d, coeffs
    return True, None, None

print(f"n=1: {check_condition(1)}")
print(f"n=2: {check_condition(2)}")
print(f"n=3: {check_condition(3)}")

import itertools

def check_n3_for_Q(q2, q1, q0):
    def f(x):
        return x**3 + q2*x**2 + q1*x + q0

    # Try k=1
    # f(a2) = f(a1)
    for a1 in range(-50, 51):
        for a2 in range(-50, 51):
            if a1 != a2 and f(a2) == f(a1):
                return True

    # Try k=2
    # f(a3) = f(a1) + f(a2)
    for a1 in range(-50, 51):
        for a2 in range(a1 + 1, 51):
            # f(a1) + f(a2) = sum_f
            sum_f = f(a1) + f(a2)
            # Now we need f(a3) = sum_f for a3 not in {a1, a2}
            # Since f(x) is cubic, it's monotonic for large x.
            # We can check a range or solve for a3.
            # To be simple, just check a range.
            for a3 in range(-100, 101):
                if a3 != a1 and a3 != a2 and f(a3) == sum_f:
                    return True

    # Try k=3
    # f(a4) = f(a1) + f(a2) + f(a3)
    for a1 in range(-30, 31):
        for a2 in range(a1 + 1, 31):
            for a3 in range(a2 + 1, 31):
                sum_f = f(a1) + f(a2) + f(a3)
                for a4 in range(-100, 101):
                    if a4 not in (a1, a2, a3) and f(a4) == sum_f:
                        return True
    return False

