def check_q0(q0):
    for a1 in range(-100, 101):
        for a2 in range(a1 + 1, 101):
            # a3^3 = a1^3 + a2^3 + q0
            val = a1**3 + a2**3 + q0
            # Check if val is a perfect cube
            if val < 0:
                root = -round((-val)**(1/3))
            else:
                root = round(val**(1/3))
            if root**3 == val:
                if root != a1 and root != a2:
                    return True, (a1, a2, root)
    return False, None

for q0 in range(1, 21):
    print(f"q0={q0}: {check_q0(q0)}")
